head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[audio > P > autoplay]<br/>Audio 컴포넌트에 연결된 오디오 파일을 자동으로 재생할지 설정합니다.",
    "validation" : [
        "Chrome 등 대부분의 최신 브라우저는 자동 재생을 기본적으로 차단합니다.",
        "autoplay 설정 시, 화면이 로딩되면 오디오 파일을 자동으로 재생합니다.",
        "빈 문자열('') 을 설정해도 자동으로 재생됩니다.",
        "브라우저의 보안/사용성 정책에 의해 음소거 처리나 자동 재생이 차단될 수 있습니다.",
        "Audio 컴포넌트는 autoplay 속성값을 출력 HTML 의 audio 태그에 전달하며, 실제 동작은 브라우저의 HTML5 audio 처리에 따라 결정됩니다.",
        "속성을 한번이라도 설정하면 속성명이 유지되고, 속성명 정의만으로 해당 기능이 설정됩니다.",
        "따라서, 소스에서 직접 속성명을 제거해야 해당 기능이 해제됩니다."
    ]
}

// 화면 로딩 시점의 자동 재생 발생 여부 기록용
scwin.gPlayLog = { "target1" : false, "target2" : false, "target3" : false };



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 화면 로딩 시 자동 재생(play) 발생 여부를 audio 요소별로 기록
    ["target1", "target2", "target3"].forEach(function (sId) {
        let el = document.querySelector("#" + sId);
        if (el === null) return;
        el.addEventListener("play", function () { scwin.gPlayLog[sId] = true; });
    });
};



// 브라우저 자동 재생 정책과 audio 요소별 자동 재생 결과 확인
scwin.btn_getAutoplayResult_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let sPolicy = (typeof navigator.getAutoplayPolicy === "function") ? navigator.getAutoplayPolicy("mediaelement") : "(해당 API 미지원 브라우저)";
    let nAutoPlayed = (scwin.gPlayLog.target1 ? 1 : 0) + (scwin.gPlayLog.target2 ? 1 : 0);

    wf_body_bottom.getObj("scwin").setReturnValue("브라우저 기본 자동 재생 차단 - 오디오 로드 완료 상태(readyState) : " + el1.readyState + " , 재생 길이(duration) : " + el1.duration + " , autoplay 설정 audio 2개 중 실제 자동 재생된 개수 : " + nAutoPlayed + " , 자동 재생 정책 : " + sPolicy);
    wf_body_bottom.getObj("scwin").setReturnValue("autoplay 를 autoplay 로 설정 - 자동 재생 발생 : " + scwin.gPlayLog.target1 + " , 재생 진행 위치(currentTime) : " + el1.currentTime + " , 재생 종료 : " + el1.ended);
    wf_body_bottom.getObj("scwin").setReturnValue("autoplay 를 빈 문자열로 설정 - 자동 재생 발생 : " + scwin.gPlayLog.target2 + " , 재생 진행 위치(currentTime) : " + el2.currentTime + " , 재생 종료 : " + el2.ended);
    wf_body_bottom.getObj("scwin").setReturnValue("브라우저 정책에 의한 처리 - target1 음소거 상태(muted) : " + el1.muted + " , 자동 재생 차단 여부 : " + (scwin.gPlayLog.target1 === false && el1.paused === true));
};



// 출력 HTML audio 태그로 전달된 autoplay 속성값과 속성 유무에 따른 설정/해제 확인
scwin.btn_getAutoplayAttr_onclick = function (e) {
    let el1 = document.querySelector("#target1");
    let el2 = document.querySelector("#target2");
    let el3 = document.querySelector("#target3");

    wf_body_bottom.getObj("scwin").setReturnValue("출력 HTML audio 태그의 autoplay 속성값 - target1 : " + JSON.stringify(el1.getAttribute("autoplay")) + " , target2 : " + JSON.stringify(el2.getAttribute("autoplay")) + " , target3 : " + JSON.stringify(el3.getAttribute("autoplay")));
    wf_body_bottom.getObj("scwin").setReturnValue("속성명 정의만으로 기능 설정 - 속성명만 정의한 target2 의 autoplay : " + el2.autoplay + " , 값을 명시한 target1 의 autoplay : " + el1.autoplay);
    wf_body_bottom.getObj("scwin").setReturnValue("소스에서 속성명 제거 시 해제 - 속성이 없는 target3 의 autoplay : " + el3.autoplay + " , 자동 재생 발생 : " + scwin.gPlayLog.target3);
};
